% Tasvirdagi obyektlarni tanib olish (Binarizatsiya va Morfologiya)
I = imread('cameraman.png');
BW = imbinarize(rgb2gray(I));
se = strel('disk', 4);
BW_cleaned = imopen(BW, se);

figure;
subplot(1,2,1); imshow(BW); title('Binar tasvir');
subplot(1,2,2); imshow(BW_cleaned); title('Obyektlar ajratilgan binar tasvir');
